        self.facing = [row[11], row[11 + 1], row[11 + 2], row[11 + 3]];
        self.pair = { let mut a = [0.0; 2]; a.copy_from_slice(&row[15..15 + 2]); a };
        self.name = StrId(word_u32(row[17]));
